import{_ as e,c as a,o as t,a6 as o,bb as l,bc as i,bd as r}from"./chunks/framework.DQNfPlXe.js";const b=JSON.parse('{"title":"使用ChatBox和AI对话","description":"","frontmatter":{"date":"2025-08-13T00:00:00.000Z","title":"使用ChatBox和AI对话"},"headers":[],"relativePath":"work/使用ChatBox和AI对话.md","filePath":"work/使用ChatBox和AI对话.md","lastUpdated":1755066998000}'),c={name:"work/使用ChatBox和AI对话.md"},d=o('<h1 id="使用chatbox和ai对话" tabindex="-1">使用ChatBox和AI对话 <a class="header-anchor" href="#使用chatbox和ai对话" aria-label="Permalink to &quot;使用ChatBox和AI对话&quot;">​</a></h1><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><p>在ChatBox <a href="https://chatboxai.app/zh" target="_blank" rel="noreferrer">官网链接</a> 中下载当前系统的最新ChatBox版本。并安装。</p><p>ChatBox有自己的服务，但价格相对高昂。优点是配置起来相对简单，只需要付钱即可使用包括AI对话、AI生图、预设MCP、无需配置的嵌入模型（用于本地个人知识库）等。</p><p>本教程提供的则是自己选择运营商，自定义设置模型、MCP、知识库相关内容。</p><p><img src="'+l+'" alt="alt text"></p><h2 id="购买ai服务运营商-token" tabindex="-1">购买AI服务运营商 token <a class="header-anchor" href="#购买ai服务运营商-token" aria-label="Permalink to &quot;购买AI服务运营商 token&quot;">​</a></h2><p>本教程推荐使用DeepSeek。价格便宜，功能够用。且可以自动添加多次相同的内容为缓存，尽量减少使用的Token量。如果你有别的用途，可自行选择其他运营商。</p><ul><li>打开 <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek 开放平台</a></li><li>点击左侧充值，按照提示充值。</li><li>充值结束后，可点击用量信息查看账户余额。</li><li>点击左侧<code>API Keys</code></li><li>点击页面中的创建 <code>API Key</code></li><li>在弹框中为创建的API key命名<div class="tip custom-block"><p class="custom-block-title">注意</p><p>这个key是软件或应用请求deepseek接口的凭证。需妥善保管，不要泄露。DeepSeek设置后无法再次展示，记得复制。</p></div></li></ul><h2 id="配置chatbox模型" tabindex="-1">配置ChatBox模型 <a class="header-anchor" href="#配置chatbox模型" aria-label="Permalink to &quot;配置ChatBox模型&quot;">​</a></h2><ul><li>打开安装好的ChatBox，点击设置，选择DeepSeek，在右侧API密钥中填写上一步获取的API Key</li><li>点击检查，查看是否设置成功。 <img src="'+i+'" alt=""></li></ul><h2 id="其他设置" tabindex="-1">其他设置 <a class="header-anchor" href="#其他设置" aria-label="Permalink to &quot;其他设置&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>设置好模型后即可正常的使用ChatBox，但由于使用中会由于默认设置导致一些问题，所以推荐配置一下。</p></div><ul><li>打开设置，在默认模型中的<code>默认对话模型</code>，<code>默认话题命名模型</code>，<code>搜索词构建模型</code>选择DeepSeek的模型</li><li>打开联网搜索，修改<code>搜索提供方</code>为<code>Bing</code>或<code>Tavily</code></li><li>打开对话设置，这里有一些在对话中展示的内容，可以按需开启或后面需要再调整。</li><li>打开常规设置，此处可以设置开机自启动等软件本身的功能。</li></ul><h2 id="对话" tabindex="-1">对话 <a class="header-anchor" href="#对话" aria-label="Permalink to &quot;对话&quot;">​</a></h2><ul><li>点击左侧<code>新对话</code>，选择一个设置好的模型，根据需求设置当前对话的prompt，开启联网搜索，然后输入一个问题，打开新世界吧！ <img src="'+r+'" alt="alt text"></li></ul><h2 id="我的搭档" tabindex="-1">我的搭档 <a class="header-anchor" href="#我的搭档" aria-label="Permalink to &quot;我的搭档&quot;">​</a></h2><p>ChatBox可以自定义预设一些被称为搭档的角色</p><p>点击左侧的<code>我的搭档</code>可以查看预设的搭档。也可以创建自己的搭档。方便日常使用。</p><p>只需要点击<code>我的搭档</code>页面中的<code>创建新的AI搭档</code>，根据表单设置prompt并保存。即可完成配置。</p>',20),h=[d];function s(p,n,_,x,k,u){return t(),a("div",null,h)}const A=e(c,[["render",s]]);export{b as __pageData,A as default};
